import{_ as n,C as t,o as e,c as s,j as i,E as r,a as l,a3 as d}from"./chunks/framework.C6R8kWFE.js";const p=JSON.parse(`{"title":"1-hafta","description":"","frontmatter":{"title":"1-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"11-sinf","link":"/11-sinf/"},"n":1,"bob":"I-bob · Dasturiy ta'minot ishlab chiqish asoslari","lessons":[{"g":1,"title":"IT ekotizimi qatlamlari, SDLC bosqichlari va jamoadagi rollar","lead":"Siz har kuni ishlatadigan ilova ortida ko'zga ko'rinmaydigan butun bir «shahar» bor: qatlamlar, serverlar va jamoa. Bugun uni xaritaga tushiramiz va o'z portfolio-loyihangiz uchun birinchi professional hujjatni yozamiz.","link":"/11-sinf/hafta-01/dars-1","slide":"/slaydlar/11-sinf/hafta-01/dars-1.html","test":"/slaydlar/11-sinf/hafta-01/dars-1-test.html"},{"g":2,"title":"Git asoslari: versiyalarni boshqarish, repozitoriy, commit, branch va merge","lead":"Bugun siz kodingiz uchun «vaqt mashinasi» yasaysiz: terminalda birinchi repozitoriyni yaratib, har o'zgarishni saqlaysiz, parallel shox ochasiz va konfliktni yechasiz. Professional dasturchilar har kuni shu buyruqlar bilan ishlaydi.","link":"/11-sinf/hafta-01/dars-2","slide":"/slaydlar/11-sinf/hafta-01/dars-2.html","test":"/slaydlar/11-sinf/hafta-01/dars-2-test.html"},{"g":3,"title":"GitHub: masofaviy repo, push/pull/clone, README, .gitignore, Issues va birinchi loyiha","lead":"Bugun kodingiz birinchi marta noutbukdan chiqib, butun dunyo ko'ra oladigan joyga boradi: GitHub. Oxirida sizda ish beruvchiga ko'rsatsa bo'ladigan birinchi haqiqiy repo bo'ladi.","link":"/11-sinf/hafta-01/dars-3","slide":"/slaydlar/11-sinf/hafta-01/dars-3.html","test":"/slaydlar/11-sinf/hafta-01/dars-3-test.html"}],"test":"/slaydlar/11-sinf/hafta-01/hafta-test.html"}},"headers":[],"relativePath":"11-sinf/hafta-01/index.md","filePath":"11-sinf/hafta-01/index.md"}`),c={name:"11-sinf/hafta-01/index.md"},h={class:"blk"},g={id:"uyga-vazifa",tabindex:"-1"};function m(u,a,b,y,f,k){const o=t("Icon");return e(),s("div",null,[i("div",h,[i("h2",g,[r(o,{name:"house"}),a[0]||(a[0]=l(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=d('<p>Har bir vazifa 20–30 daqiqa. Parol, token, maxfiy kalit va shaxsiy ma&#39;lumotlarni hech kimga yubormang va fayllarga yozmang: topshirishda faqat fayl yoki ochiq repo havolasi kerak.</p><h3 id="_1-dars-uchun-it-ekotizimi-va-sdlc" tabindex="-1">1-dars uchun (IT ekotizimi va SDLC) <a class="header-anchor" href="#_1-dars-uchun-it-ekotizimi-va-sdlc" aria-label="Permalink to &quot;1-dars uchun (IT ekotizimi va SDLC)&quot;">​</a></h3><p><strong>1-topshiriq: «Portfolio-loyiha: talab»</strong></p><ol><li>Darsda boshlagan <code>SRS-mini.md</code> faylini yakunlang. Unda bo&#39;lishi kerak: bir jumlalik maqsad; 5 ta user story; har bir user story uchun kamida 2 ta qabul mezoni; «loyiha nimani qilmaydi» bo&#39;limida 3 ta cheklov.</li><li>Qabul mezonlarini o&#39;lchanadigan qilib yozing: «chiroyli», «tez» kabi mavhum so&#39;zlar o&#39;rniga son yoki tekshiriladigan shart yozing.</li><li>Sevimli ilovangizning 4 qatlamli xaritasini (klient, ilova, platforma, infratuzilma) toza chizing: har qatlamda kamida 2 ta komponent bo&#39;lsin. Rasm yoki foto qiling.</li><li>Terminalda <code>git --version</code> buyrug&#39;ini ishga tushiring va natijani tekshiring: keyingi darsda Git bilan ishlaymiz.</li></ol><p><strong>Kutiladigan natija:</strong> <code>SRS-mini.md</code> (5 user story, 10 dan ortiq o&#39;lchanadigan qabul mezoni, 3 cheklov); ilova xaritasining rasmi; <code>git --version</code> versiya raqamini chiqaradi. <strong>Topshirish:</strong> <code>SRS-mini.md</code> fayli, xarita rasmi va <code>git --version</code> natijasining skrinshoti yoki ko&#39;chirilgan matni.</p><h3 id="_2-dars-uchun-git-asoslari-commit-branch-merge" tabindex="-1">2-dars uchun (Git asoslari: commit, branch, merge) <a class="header-anchor" href="#_2-dars-uchun-git-asoslari-commit-branch-merge" aria-label="Permalink to &quot;2-dars uchun (Git asoslari: commit, branch, merge)&quot;">​</a></h3><p><strong>2-topshiriq: <code>dev-journal</code> ni boyiting</strong></p><ol><li><code>dev-journal</code> repozitoriyasida <code>.gitignore</code> faylini yarating. Unda kamida <code>.env</code> va <code>__pycache__/</code> qatorlari bo&#39;lsin.</li><li>Uch kun uchun <code>notes/kun-1.md</code>, <code>notes/kun-2.md</code>, <code>notes/kun-3.md</code> yozuvlarini yozing. Har bir fayl alohida commit bo&#39;lsin, xabarlar Conventional Commits uslubida (masalan, <code>docs: ...</code>).</li><li><code>feature/skills</code> shoxini oching, unda bitta o&#39;zgarish qiling va commit qiling, so&#39;ng uni <code>main</code> ga merge qiling.</li><li><code>git log --oneline --graph</code> natijasini <code>log.txt</code> fayliga saqlang va shu faylni ham commit qiling.</li></ol><p><strong>Kutiladigan natija:</strong> <code>git log</code> da 3 ta kunlik yozuv commiti, <code>.gitignore</code> commiti, merge va <code>log.txt</code> commiti ko&#39;rinadi; grafikda <code>feature/skills</code> shoxi <code>main</code> ga qo&#39;shilgani bilinadi; <code>git status</code> toza. <strong>Topshirish:</strong> <code>log.txt</code> fayli va <code>git status</code> natijasi. Keyingi darsda bu repoz GitHub&#39;ga yuklanadi.</p><h3 id="_3-dars-uchun-github" tabindex="-1">3-dars uchun (GitHub) <a class="header-anchor" href="#_3-dars-uchun-github" aria-label="Permalink to &quot;3-dars uchun (GitHub)&quot;">​</a></h3><p><strong>3-topshiriq: <code>dev-log</code> ni davom ettiring</strong></p><ol><li>Darsda yaratgan <code>dev-log</code> repongizga yana 2 ta mazmunli commit qo&#39;shing (masalan, <code>todo.py</code> ga yangi buyruq va <code>README.md</code> ni yaxshilash). Commit xabari nima o&#39;zgarganini aniq aytsin.</li><li>GitHub&#39;da bitta Issue oching va uni commit xabaridagi <code>Closes #N</code> (o&#39;z Issue raqamingiz) orqali yoping.</li><li>O&#39;zgarishlarni <code>git push</code> bilan GitHub&#39;ga yuboring va repo ochiq (public) ekanini tekshiring.</li><li>Repo havolasini mentorga yuboring.</li></ol><p><strong>Kutiladigan natija:</strong> GitHub&#39;dagi <code>dev-log</code> da yangi 2 ta commit; Issue <code>Closed</code> holatida va uni yopgan commitga havola bor; <code>README.md</code> va <code>.gitignore</code> joyida; repo havolasi brauzerda (kirmasdan) ochiladi. <strong>Topshirish:</strong> faqat ochiq repo havolasi (<code>https://github.com/&lt;nom&gt;/dev-log</code>). Parol, token yoki kalit yubormang.</p>',13))])])}const z=n(c,[["render",m]]);export{p as __pageData,z as default};
